18	/**
19	 * 公告曝光频控 API。
20	 */
21	@RestController
22	@RequestMapping("/api/exposure")
23	public class ExposureController {
24	
25	    private final ExposureService exposureService;
26	
27	    public ExposureController(ExposureService exposureService) {
28	        this.exposureService = exposureService;
29	    }
30	
31	    /** 创建公告（额度创建时固定）。 */
32	    @PostMapping("/campaigns")
33	    public ResponseEntity<CampaignResponse> createCampaign(@Valid @RequestBody CreateCampaignRequest request) {
34	        return ResponseEntity.status(HttpStatus.CREATED).body(exposureService.createCampaign(request));
35	    }
36	
37	    /** 申请曝光：创建 60 秒有效预占并占用两级额度。 */
38	    @PostMapping("/reservations")
39	    public ResponseEntity<ReservationResponse> apply(@Valid @RequestBody ApplyExposureRequest request) {
40	        return ResponseEntity.status(HttpStatus.CREATED).body(exposureService.apply(request));
41	    }
42	
43	    /** 预占明细。 */
44	    @GetMapping("/reservations/{reservationId}")
45	    public ReservationResponse getReservation(@PathVariable String reservationId) {
46	        return exposureService.getReservation(reservationId);
47	    }
48	
49	    /** 确认预占：必须在到期时刻之前。 */
50	    @PostMapping("/reservations/{reservationId}/confirm")
51	    public ReservationResponse confirm(@PathVariable String reservationId,
52	                                       @Valid @RequestBody ReservationActionRequest request) {
53	        return exposureService.confirm(reservationId, request);
54	    }
55	
56	    /** 取消预占：仅 RESERVED 可取消并释放两级额度。 */
57	    @PostMapping("/reservations/{reservationId}/cancel")
58	    public ReservationResponse cancel(@PathVariable String reservationId,
59	                                      @Valid @RequestBody ReservationActionRequest request) {
60	        return exposureService.cancel(reservationId, request);
61	    }
62	
63	    /**
64	     * 按公告/访客/UTC 日查询额度；visitorId 缺省仅返回公告当日总额度。
